(window.LADDER_CARDS=window.LADDER_CARDS||{})["24·econ"]=[{"q": "Workers lose jobs at rate s and find them at rate f. Where does the share out of work settle?", "a": "s/(s + f)", "w": ["s/f", "f/(s + f)", "0"], "why": "Two-flows: s(1 − u) = fu."}, {"q": "s = 0.01 and f = 0.19 a month. The share out of work at rest?", "a": "0.05", "w": ["0.0526", "0.01", "0.19"], "why": "0.01/0.20."}, {"q": "At rest the share out of work holds steady. Are the people out of work the same ones each month?", "a": "no: as many find work as lose it", "w": ["yes: nobody moves at rest", "yes: only they can lose a job", "no: everyone changes each month"], "why": "The flows balance; they do not stop."}, {"q": "How fast does the gap to the resting share close?", "a": "at the rate s + f", "w": ["at the rate s", "at the rate f − s", "at the rate sf"], "why": "u′ = −(s + f)(u − u*)."}, {"q": "The growth rate of a product xy?", "a": "the sum of the two growth rates", "w": ["the product of the two growth rates", "the larger growth rate", "the average of the two"], "why": "Growth-rates-add, from the product technique."}, {"q": "Money grows 7 in 100 a year, its speed is steady, output grows 3. Prices grow by?", "a": "4 in 100", "w": ["7 in 100", "10 in 100", "21 in 100"], "why": "7 + 0 − 3."}, {"q": "x′ = −py and y′ = qx. What rule does x obey alone?", "a": "x″ = −pqx", "w": ["x″ = pqx", "x′ = −pqx", "x″ = −(p + q)x"], "why": "Each-steers: steady swinging."}, {"q": "Jobs and the workers’ share swing together. Which peaks first?", "a": "jobs, a quarter swing ahead", "w": ["the workers’ share", "they peak together", "neither ever peaks"], "why": "The share is still rising at the top of jobs."}, {"q": "A pull to rest, c above 0, is put into the cycle. What becomes of qx² + py²?", "a": "it can only fall", "w": ["it is still kept", "it can only rise", "it swings up and down"], "why": "Dying-swing: its rate is −2cqx²."}, {"q": "Its accepted name, for the cycle of jobs and the wage share?", "a": "the Goodwin model", "w": ["the multiplier", "the quantity theory of money", "the logistic model"], "why": "A growth cycle, 1967."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["25·econ"]=[{"q": "With y = k^α and α = ⅓, eight times the machines per worker gives how much output per worker?", "a": "twice as much", "w": ["eight times", "a third more", "the same"], "why": "8^(1/3) = 2: each more adds less."}, {"q": "What is the rule for machines per worker?", "a": "k′ = s k^α − (δ + n)k", "w": ["k′ = s k^α", "k′ = (s − δ)k", "k′ = δk − s k^α"], "why": "Saving against wear and new workers."}, {"q": "Where does k come to rest?", "a": "(s/(δ + n))^(1/(1 − α))", "w": ["s/(δ + n)", "(δ + n)/s", "s^α"], "why": "The resting-point technique."}, {"q": "Why does the resting point hold?", "a": "the slope of k′ there is −(1 − α)(δ + n), below 0", "w": ["k′ is positive there", "saving is constant", "α is a third"], "why": "Stability by the sign of a slope (24k)."}, {"q": "Saving rises from 0.2 to 0.3, with α = ⅓. What happens to output per worker at rest?", "a": "it rises about 22%, once", "w": ["it grows faster for ever", "it rises 50%", "nothing"], "why": "The level technique: y* ∝ s^(1/2)."}, {"q": "What keeps output per worker growing in the long run?", "a": "better ways of working", "w": ["more saving", "more workers", "less wear"], "why": "Saving lifts the level, not the growth."}, {"q": "With α = ⅓ and δ + n = 0.06, about how long does half the gap to rest take to close?", "a": "17 years", "w": ["4 years", "2 years", "70 years"], "why": "ln 2/0.04."}, {"q": "In x_t = c(1 + v)x_(t−1) − cv x_(t−2), the roots are a flipped pair z, z̄. What is |z|²?", "a": "cv", "w": ["c(1 + v)", "c + v", "1/cv"], "why": "The product of the roots (25c; 20·cb8)."}, {"q": "When do the waves on the way to rest die away?", "a": "when cv < 1", "w": ["when c < 1", "when v < 1", "always"], "why": "The wave technique: each year |z| = √(cv) times the last."}, {"q": "Roots of size √0.5 at a turn of π/4. How many years does each wave last?", "a": "8", "w": ["4", "2", "π/4"], "why": "2π/θ."}];
